unsafe fn updateHashChain(
    mut hash: *mut Hash,
    mut wpos: size_t,
    mut hashval: c_uint,
    mut numzeros: c_ushort,
) {
    let hash_view: &Hash = unsafe {
        // SAFETY: caller provides a valid `hash` pointer for the duration of this function.
        &*hash
    };
    let head = hash_view.head;
    let chain = hash_view.chain;
    let val = hash_view.val;
    let headz = hash_view.headz;
    let chainz = hash_view.chainz;
    let zeros = hash_view.zeros;

    *val.offset(wpos as isize) = hashval as c_int;

    let head_hashval = *head.offset(hashval as isize);
    if head_hashval != -(1 as c_int) {
        *chain.offset(wpos as isize) = head_hashval as c_ushort;
    }
    *head.offset(hashval as isize) = wpos as c_int;

    *zeros.offset(wpos as isize) = numzeros;

    let headz_numzeros = *headz.offset(numzeros as isize);
    if headz_numzeros != -(1 as c_int) {
        *chainz.offset(wpos as isize) = headz_numzeros as c_ushort;
    }
    *headz.offset(numzeros as isize) = wpos as c_int;
}

